for name, also, role, aff, note in P:
    cmd = ['/usr/bin/python3', 'tools/history-db.py', 'person', '--name', name,
           '--role', role, '--affiliation', aff, '--note', note,
           '--bibkey', B, '--topic', T, '--indigenous']
    if name in ('Frank Melms',):
        cmd.remove('--indigenous')
    if also:
        cmd += ['--also', also]
    r = subprocess.run(cmd, capture_output=True, text=True)
    print(name, '|', (r.stdout + r.stderr).strip()[:110])
